package com.silverroom.camera;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.graphics.*;import android.location.*;import android.media.ExifInterface;import android.net.Uri;import android.os.*;import android.provider.*;import org.json.*;import java.io.*;import java.security.*;import java.util.*;

/** Byte-preserving import/export and opt-in foreground location; rendering always uses new copies. */
final class MediaArchive implements LocationListener {
    static final int IMPORT=301,COVER=302,CSV=303,LOCATION=304;
    final StudioController studio;final MainActivity a;private String importRoll,pendingCsv,coverTable;private JSONObject coverRecord;private final LocationManager locations;private volatile Location lastLocation;private boolean listening;
    MediaArchive(StudioController s){studio=s;a=s.a;locations=(LocationManager)a.getSystemService(Context.LOCATION_SERVICE);}
    private Intent photoPicker(boolean multiple){Intent i=new Intent(MediaStore.ACTION_PICK_IMAGES).setType("image/*");if(multiple)i.putExtra(MediaStore.EXTRA_PICK_IMAGES_MAX,50);if(Build.VERSION.SDK_INT>=35)i.putExtra(MediaStore.EXTRA_PICK_IMAGES_LAUNCH_TAB,MediaStore.PICK_IMAGES_TAB_IMAGES);return i;}
    void importPhotos(String roll){if(a.busy||a.exporting)return;importRoll=roll;pick(IMPORT,true);}
    void pickCover(String table,JSONObject record){coverTable=table;coverRecord=RollRepository.copy(record);pick(COVER,false);}
    private void pick(int request,boolean multiple){try{a.startActivityForResult(photoPicker(multiple),request);}catch(Exception e){try{a.startActivityForResult(new Intent(Intent.ACTION_PICK,MediaStore.Images.Media.EXTERNAL_CONTENT_URI).setType("image/*").putExtra(Intent.EXTRA_ALLOW_MULTIPLE,multiple),request);}catch(Exception ex){a.toast("未找到系统相册选择器");}}}
    boolean result(int request,int code,Intent intent){if(request!=IMPORT&&request!=COVER&&request!=CSV)return false;if(code!=Activity.RESULT_OK||intent==null)return true;if(request==CSV){Uri target=intent.getData();String text=pendingCsv;pendingCsv=null;if(target!=null&&text!=null)StudioUi.work(a,()->{try(OutputStream out=a.getContentResolver().openOutputStream(target)){if(out==null)throw new IOException("无法写入 CSV");out.write(text.getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(IOException e){throw new IllegalStateException(e);}},()->a.toast("CSV 已导出"));return true;}
        List<Uri> uris=new ArrayList<>();if(intent.getClipData()!=null)for(int i=0;i<intent.getClipData().getItemCount()&&i<50;i++){Uri u=intent.getClipData().getItemAt(i).getUri();if(u!=null&&!uris.contains(u))uris.add(u);}if(intent.getData()!=null&&!uris.contains(intent.getData()))uris.add(intent.getData());if(uris.isEmpty())return true;
        if(request==COVER){JSONObject target=coverRecord;String table=coverTable;if(target==null)return true;StudioUi.work(a,()->{try{File dir=new File(a.getFilesDir(),"covers");dir.mkdirs();File file=new File(dir,UUID.randomUUID()+".img");copyUri(uris.get(0),file);target.put("cover",file.getName());if(table.equals("rolls"))studio.repository.saveRoll(target);else studio.repository.saveProfile(table,target);}catch(Exception e){throw new IllegalStateException(e);}},()->{a.toast("封面已保存");if(a.page==2)studio.archive.render();});return true;}
        final String roll=importRoll==null?studio.rollId():importRoll;a.exporting=true;a.worker.execute(()->{int count=0;String failure="";for(Uri uri:uris){try{importOne(uri,roll);count++;}catch(Exception|OutOfMemoryError e){failure=e.getMessage();}}int done=count;String why=failure;a.main.post(()->{a.exporting=false;a.refreshLatest();if(a.page==2)studio.archive.render();a.toast("已导入 "+done+" / "+uris.size()+" 张"+(why==null||why.isEmpty()?"":"\n部分未完成："+why));});});return true;
    }
    private void copyUri(Uri uri,File file)throws IOException{try(InputStream in=a.getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException("无法读取照片");copy(in,out);out.getFD().sync();}}
    static void copy(InputStream in,OutputStream out)throws IOException{byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}
    private String name(Uri uri){try(Cursor c=a.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception ignored){}return "import.jpg";}
    static String digest(File file)throws Exception{MessageDigest sha=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] block=new byte[65536];int n;while((n=in.read(block))!=-1)sha.update(block,0,n);}StringBuilder out=new StringBuilder();for(byte b:sha.digest())out.append(String.format(Locale.US,"%02x",b&255));return out.toString();}
    private void importOne(Uri uri,String roll)throws Exception{
        String id=a.reservePhotoId(System.currentTimeMillis());File original=new File(a.rollDir,id+"_original.jpg"),preview=new File(a.rollDir,id+".jpg");Bitmap image=null;try{
            copyUri(uri,original);String sha=digest(original),mime=a.getContentResolver().getType(uri),filename=name(uri);image=a.decode(original,4096);a.writeJpeg(image,preview);JSONObject j=RollRepository.object("imported",true,"stock",0,"strength",0,"source_mime",mime==null?"image/jpeg":mime,"source_name",filename,"source_sha256",sha,"width",image.getWidth(),"height",image.getHeight(),"pixels_upright",true,"lens","相册导入","archive_roll",roll,"archive_snapshot",Optional.ofNullable(studio.repository.find("rolls",roll)).orElse(new JSONObject()).toString());image.recycle();image=null;
            try{ExifInterface exif=new ExifInterface(original.getAbsolutePath());String date=exif.getAttribute(ExifInterface.TAG_DATETIME_ORIGINAL);if(PrintMetadata.validDate(date))j.put("source_datetime",date);JSONObject source=RollRepository.object("make",exif.getAttribute(ExifInterface.TAG_MAKE),"model",exif.getAttribute(ExifInterface.TAG_MODEL));int iso=exif.getAttributeInt(ExifInterface.TAG_ISO_SPEED_RATINGS,0);double time=exif.getAttributeDouble(ExifInterface.TAG_EXPOSURE_TIME,0),f=exif.getAttributeDouble(ExifInterface.TAG_F_NUMBER,0),mm=exif.getAttributeDouble(ExifInterface.TAG_FOCAL_LENGTH,0);if(iso>0)source.put("iso",iso);if(time>0)source.put("exposure_ns",(long)(time*1e9));if(f>0)source.put("aperture",f);if(mm>0)source.put("focal_mm",mm);int eq=exif.getAttributeInt(ExifInterface.TAG_FOCAL_LENGTH_IN_35MM_FILM,0);if(eq>0)source.put("mm",eq);j.put("source_capture",source);}catch(Exception ignored){}
            a.saveMeta(id,j);studio.repository.photo(id,roll,j.optString("archive_snapshot"),j,false);
            if(!digest(original).equals(sha))throw new IOException("原片校验失败");
        }catch(Exception e){if(!new File(a.rollDir,id+".json").exists()){original.delete();preview.delete();}throw e;}finally{if(image!=null)image.recycle();}
    }
    void originals(List<String> requested){if(a.busy||a.exporting)return;List<String> ids=new ArrayList<>();for(String id:requested)if(NegativeStore.valid(id))ids.add(id);if(ids.isEmpty()){a.toast("未选择照片");return;}a.exporting=true;a.worker.execute(()->{int done=0;String error="";for(String id:ids)try{JSONObject j=a.readMeta(id);String mime=j.optString("source_mime","image/jpeg"),name=j.optString("source_name","FC_ORIGINAL_"+id+".jpg");exportFile(new File(a.rollDir,id+"_original.jpg"),name,mime);done++;}catch(Exception e){error=e.getMessage();}int n=done;String why=error;a.main.post(()->{a.exporting=false;a.toast("已导出 "+n+" / "+ids.size()+" 份原件"+(why.isEmpty()?"":"\n"+why));});});}
    private Uri exportFile(File file,String name,String mime)throws IOException{ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"FC_"+System.currentTimeMillis()+"_"+name.replaceAll("[\\\\/:*?\"<>|]","_"));v.put(MediaStore.Images.Media.MIME_TYPE,mime);v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/Silverroom/Exports");v.put(MediaStore.Images.Media.IS_PENDING,1);Uri uri=a.getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IOException("相册文件创建失败");try{try(InputStream in=new FileInputStream(file);OutputStream out=a.getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("相册写入失败");copy(in,out);}v.clear();v.put(MediaStore.Images.Media.IS_PENDING,0);if(a.getContentResolver().update(uri,v,null,null)<1)throw new IOException("相册提交失败");return uri;}catch(IOException e){a.getContentResolver().delete(uri,null,null);throw e;}}
    void csv(String roll){a.worker.execute(()->{try{String text=studio.repository.csv(roll);a.main.post(()->{pendingCsv=text;try{a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/csv").putExtra(Intent.EXTRA_TITLE,"FancyCamera-"+System.currentTimeMillis()+".csv"),CSV);}catch(Exception e){a.toast("没有可用的文档保存入口");}});}catch(Exception e){a.main.post(()->a.toast("CSV 未完成："+e.getMessage()));}});}
    void saveReference(String id,PreviewAtlas atlas){a.worker.execute(()->{Bitmap bitmap=null;try{File dir=new File(a.getFilesDir(),"meter-references");dir.mkdirs();File file=new File(dir,id+".jpg");bitmap=Bitmap.createBitmap(atlas.pixels(atlas.index(0)),atlas.tileWidth,atlas.tileHeight,Bitmap.Config.ARGB_8888);try(FileOutputStream out=new FileOutputStream(file)){if(!bitmap.compress(Bitmap.CompressFormat.JPEG,90,out))throw new IOException("参考图编码失败");}studio.repository.reference(id,file.getName());}catch(Exception e){a.main.post(()->a.toast("测光记录已保留，参考图未保存"));}finally{if(bitmap!=null)bitmap.recycle();}});}
    void locationEnabled(boolean on){a.prefs.edit().putBoolean("studio_location",on).apply();if(on&&a.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&a.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.ACCESS_FINE_LOCATION},LOCATION);else resumeLocation();}
    void resumeLocation(){stopLocation();if(!a.resumed||!a.prefs.getBoolean("studio_location",false)||locations==null)return;if(a.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&a.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)return;for(String provider:new String[]{LocationManager.NETWORK_PROVIDER,LocationManager.GPS_PROVIDER})try{if(locations.isProviderEnabled(provider)){locations.requestLocationUpdates(provider,5000,10,this,Looper.getMainLooper());listening=true;}}catch(SecurityException|IllegalArgumentException ignored){}}
    void stopLocation(){if(locations!=null&&listening)locations.removeUpdates(this);listening=false;}
    void addLocation(JSONObject data){Location l=lastLocation;if(!a.prefs.getBoolean("studio_location",false)||l==null||SystemClock.elapsedRealtimeNanos()-l.getElapsedRealtimeNanos()>120000000000L)return;try{data.put("location",RollRepository.object("latitude",l.getLatitude(),"longitude",l.getLongitude(),"accuracy",l.getAccuracy(),"time",l.getTime()));}catch(JSONException ignored){}}
    @Override public void onLocationChanged(Location value){lastLocation=new Location(value);}@Override public void onProviderDisabled(String provider){}@Override public void onProviderEnabled(String provider){}@Override public void onStatusChanged(String provider,int status,Bundle extras){}
    void close(){stopLocation();}
}
